function subtest_config_results(template, configType) {
  const type = configType === "pop" ? "pop3" : configType;

  Assert.equal(
    template.querySelector("#incomingType").textContent,
    type,
    "Incoming type should be expected type"
  );

  Assert.equal(
    template.querySelector("#outgoingType").textContent,
    "smtp",
    `${configType}: Outgoing type should be expected type`
  );

  Assert.equal(
    template.querySelector("#incomingHost").textContent,
    `${configType}.mail.momo.invalid`,
    `${configType}: Incoming host should be ${configType}.mail.momo.invalid`
  );

  Assert.equal(
    template.querySelector("#outgoingHost").textContent,
    "smtp.mail.momo.invalid",
    `${configType}: Outgoing host should be expected host`
  );

  Assert.equal(
    template.querySelector("#incomingPort").textContent,
    configType === "pop" ? "995" : "993",
    `${configType}: Incoming port should be as expected`
  );

  Assert.equal(
    template.querySelector("#outgoingPort").textContent,
    "465",
    `${configType}: Outgoing port should be as expected`
  );

  Assert.equal(
    template.l10n.getAttributes(template.querySelector("#sharedSocketType")).id,
    "account-hub-result-security-ssl",
    `${configType}: Incoming socketType should be as expected`
  );

  Assert.equal(
    template.l10n.getAttributes(
      template.querySelector("#sharedAuthenticationType")
    ).id,
    "account-hub-result-authentication-password",
    `${configType}: Authentication type should be expected`
  );

  Assert.equal(
    template.querySelector("#sharedUsername").textContent,
    "john.doe",
    `${configType}: Incoming username should be expected username`
  );
}
